    .replace(/<script[^>]*babel[^>]*><\/script>\s*/gi, '')
    .replace(/<script[^>]*app\.jsx[^>]*><\/script>\s*/gi, '');

  const reactSrc = fs.readFileSync(require.resolve('react/umd/react.development.js'), 'utf8');
  const reactDomSrc = fs.readFileSync(require.resolve('react-dom/umd/react-dom.development.js'), 'utf8');

  const inlineScripts =
    `<script>${reactSrc}</script>` +
    `<script>${reactDomSrc}</script>` +
    `<script>${compiled}</script>`;

  shell = shell.replace('</body>', `${inlineScripts}</body>`);

  const dom = new JSDOM(shell, {
    runScripts: 'dangerously',
    pretendToBeVisual: true,
    url: 'http://localhost/'
